<template>
  <PlatformAdminShell title="模型试用" description="独立检查真实模型通道。只有点击“发送测试”才会提交生成，测试过程也会进入任务日志。">
    <template #actions><button class="btn" @click="loadModels" :disabled="loading"><RefreshCw :size="13" />刷新模型</button><NuxtLink class="btn" to="/admin/channels"><Settings2 :size="13" />配置渠道</NuxtLink></template>
    <div class="playground-grid"><section class="card test-compose"><div class="test-type-tabs"><button v-for="item in kinds" :key="item.key" :class="{on:kind===item.key}" :disabled="sending||uploading" @click="kind=item.key"><component :is="item.icon" :size="14" />{{ item.label }}</button></div><div class="test-compose-body"><label class="test-field">测试模型<select class="input" v-model="selectedConfigId" aria-label="测试模型"><option v-for="model in availableModels" :key="model.id" :value="String(model.id)">{{ model.display_name || model.name }} · {{ model.channel_name || model.provider }} · {{ modelsOf(model)[0] }}</option></select></label><p v-if="!availableModels.length" class="test-note">当前没有启用的{{ kindLabel }}模型，请先在模型渠道中添加。</p><label class="test-field">测试提示词<textarea class="input test-prompt" v-model="prompt" rows="7" :placeholder="kind==='text'?'输入你希望模型回答的内容':'输入本次测试的完整生成提示词'" /></label><p v-if="selectedConfig?.capabilities?.streaming_mode==='final_response'" class="test-note" role="status">当前所选协议按整轮返回；完成后显示公开内容，运行中可查看任务阶段和进度。</p><ModelParameterFields :config="selectedConfig" v-model="parameters" /><section v-if="kind!=='text'" class="test-references"><div class="test-reference-heading"><span>参考素材 <small>按所选协议能力传递，保留上传顺序</small></span><button class="btn btn-sm" @click="fileInput?.click()" :disabled="uploading"><Upload :size="12" />{{ uploading?'正在上传…':'上传素材' }}</button><input ref="fileInput" hidden type="file" multiple accept="image/*,video/*,audio/*" @change="uploadFiles" /></div><div v-for="(reference,index) in references" :key="reference.path" class="test-reference-row"><img v-if="reference.kind==='image'" :src="mediaUrl(reference.path)" alt="参考图片" /><span v-else class="test-reference-icon"><component :is="reference.kind==='video'?Video:AudioLines" :size="17" /></span><span><strong>{{ reference.name }}</strong><small>{{ reference.kind==='image'?'图片':reference.kind==='video'?'视频':'音频' }} · 第 {{ index+1 }} 项</small></span><button class="btn btn-icon btn-sm" @click="references.splice(index,1)" aria-label="移除素材"><X :size="13" /></button></div><p v-if="!references.length" class="test-note">可选。纯文字视频、图片不需要上传参考素材。</p></section><p class="test-warning"><CircleAlert :size="13" />发送真实请求可能消耗你的服务额度。这里不自动重试失败任务。</p><p v-if="error" class="test-error" role="alert">{{ error }}</p><button class="btn btn-primary test-send" :disabled="sending||uploading||!selectedConfig||!prompt.trim()" @click="send"><Send :size="14" />{{ sending?'正在提交…':'发送'+kindLabel+'测试' }}</button></div></section>
      <section class="card test-results"><header><div><span>TEST RESULT</span><h2>结果与运行过程</h2></div><button v-if="selectedRecord" class="btn btn-sm" @click="logOpen=true"><Activity :size="13" />查看完整日志</button></header><div v-if="records.length" class="test-history"><button v-for="record in records" :key="record.id" :class="{on:record.id===selectedRecordId}" @click="selectedRecordId=record.id">{{ record.kind==='image'?'图片':record.kind==='video'?'视频':'文字' }} · {{ record.modelLabel }}<i :class="record.status"></i></button></div><div v-if="selectedRecord" class="test-result-body"><div class="test-result-meta"><span :class="['test-state',selectedRecord.status]">{{ stateLabel(selectedRecord.status) }}</span><span>{{ selectedRecord.stage || '准备请求' }}</span><span>{{ seconds(selectedRecord.elapsed_seconds) }}</span></div><div v-if="selectedRecord.progress!=null" class="test-progress"><span>上游进度 {{ selectedRecord.progress }}%</span><div><i :style="{width:selectedRecord.progress+'%'}"></i></div></div><p v-if="selectedRecord.error" class="test-error" role="alert">{{ selectedRecord.error }}</p><pre v-if="selectedRecord.result?.text!==undefined" class="test-output">{{ selectedRecord.result.text }}</pre><img v-else-if="selectedRecord.kind==='image'&&resultUrl" class="test-result-image" :src="resultUrl" alt="模型测试图片" /><video v-else-if="selectedRecord.kind==='video'&&resultUrl" class="test-result-video" :src="resultUrl" controls playsinline /><div v-else-if="active(selectedRecord)" class="test-idle"><Loader2 :size="31" class="animate-spin" /><h3>模型正在处理</h3><p>持续查询本次任务，不会重复提交生成。</p></div><div v-else class="test-idle"><CircleCheck :size="29" /><p>{{ selectedRecord.status==='completed'?'任务已结束，可查看完整记录。':'本次请求已结束。' }}</p></div><div v-if="outputMedia.length>1" class="test-gallery"><button v-for="(output,index) in outputMedia" :key="index" :class="{on:selectedOutputIndex===index}" @click="selectedOutputIndex=index"><img v-if="selectedRecord.kind==='image'" :src="mediaUrl(output.local_path||output.result_url)" :alt="'输出 '+(index+1)" /><Video v-else :size="20" /><span>第 {{ index+1 }} {{ selectedRecord.kind==='image'?'张':'条' }}</span></button></div><div v-if="outputMedia.length" class="test-download-list"><a v-for="(output,index) in outputMedia" :key="index" :href="mediaUrl(output.local_path||output.result_url)" download target="_blank" rel="noopener">下载{{ selectedRecord.kind==='image'?'图片':'视频' }} {{ index+1 }}<ArrowUpRight :size="11" /></a></div><div v-if="selectedRecord.result?.usage" class="test-usage"><span>实际用量</span><pre>{{ JSON.stringify(selectedRecord.result.usage,null,2) }}</pre></div><a v-if="resultUrl" class="btn btn-sm" :href="resultUrl" download target="_blank" rel="noopener">打开 / 下载结果<ArrowUpRight :size="12" /></a></div><div v-else class="test-idle"><FlaskConical :size="36" /><h3>选择模型，发送一条测试</h3><p>文字、图片、视频均使用服务器上配置的真实通道。</p></div></section></div>
    <Teleport to="body"><div v-if="logOpen&&selectedRecord" class="test-log-overlay" @click.self="logOpen=false"><div class="test-log-dialog"><TaskCenter :initial-task-id="selectedRecord.activity_task_id||selectedRecord.id" embedded closable @close="logOpen=false" /></div></div></Teleport>
  </PlatformAdminShell>
</template>
<script setup>
import { computed,onBeforeUnmount,onMounted,ref,watch } from 'vue'
import { RefreshCw,Settings2,Type,Image as ImageIcon,Video,AudioLines,Upload,X,CircleAlert,Send,Activity,Loader2,CircleCheck,ArrowUpRight,FlaskConical } from 'lucide-vue-next'
import PlatformAdminShell from '~/components/PlatformAdminShell.vue'
import ModelParameterFields from '~/components/ModelParameterFields.vue'
import TaskCenter from '~/components/TaskCenter.vue'
import { aiConfigAPI,modelTestAPI,uploadAPI } from '~/composables/useApi'
import { initialModelParameters } from '~/utils/model-parameters.js'
const selectedOutputIndex=ref(0)
const kind=ref('text'),models=ref([]),selectedConfigId=ref(''),parameters=ref({}),prompt=ref(''),references=ref([]),fileInput=ref(null),uploading=ref(false),sending=ref(false),loading=ref(false),error=ref(''),records=ref([]),selectedRecordId=ref(''),logOpen=ref(false)
const kinds=[{key:'text',label:'文字',icon:Type},{key:'image',label:'图片',icon:ImageIcon},{key:'video',label:'视频',icon:Video}],kindLabel=computed(()=>kinds.find(item=>item.key===kind.value)?.label)
const availableModels=computed(()=>models.value.filter(model=>model.service_type===kind.value&&model.is_active)),selectedConfig=computed(()=>availableModels.value.find(model=>String(model.id)===selectedConfigId.value)),selectedRecord=computed(()=>records.value.find(record=>record.id===selectedRecordId.value))
const mediaUrl=value=>value&&(/^(?:https?:|\/)/u.test(value)?value:'/'+value),outputMedia=computed(()=>{const result=selectedRecord.value?.result;const list=selectedRecord.value?.kind==='image'?result?.output_images:result?.output_videos;return Array.isArray(list)&&list.length?list:result&&(result.local_path||result.result_url||result.url)?[{local_path:result.local_path,result_url:result.result_url||result.url}]:[]}),resultUrl=computed(()=>{const output=outputMedia.value[selectedOutputIndex.value]||outputMedia.value[0];return mediaUrl(output?.local_path||output?.result_url)}),active=record=>['running','queued','pending','processing'].includes(record?.status)
const modelsOf=model=>Array.isArray(model.model)?model.model:[model.model],seconds=value=>typeof value==='number'?`${Math.round(value)} 秒`:'耗时未提供',stateLabel=value=>({running:'执行中',queued:'排队中',pending:'排队中',processing:'执行中',completed:'已完成',failed:'失败',interrupted:'已中断'}[value]||value)
let alive=true,pollTimer=null
async function loadModels(){loading.value=true;error.value='';try{models.value=await aiConfigAPI.list();if(!selectedConfig.value)selectedConfigId.value=String(availableModels.value[0]?.id||'')}catch(failure){error.value=failure.message}finally{loading.value=false}}
watch(selectedRecordId,()=>{selectedOutputIndex.value=0})
watch(kind,()=>{selectedConfigId.value=String(availableModels.value[0]?.id||'');references.value=[];error.value=''})
watch(selectedConfig,config=>{parameters.value=initialModelParameters(config)})
async function uploadFiles(event){const files=[...(event.target.files||[])];event.target.value='';uploading.value=true;error.value='';try{for(const file of files){const type=file.type.startsWith('video/')?'video':file.type.startsWith('audio/')?'audio':'image';const response=await uploadAPI[type](file);if(!alive)return;references.value.push({kind:type,path:response.path||response.url||response.local_path,name:file.name})}}catch(failure){error.value=failure.message}finally{uploading.value=false}}
async function send(){if(sending.value||!selectedConfig.value||!prompt.value.trim())return;sending.value=true;error.value='';const config=selectedConfig.value;try{const body={config_id:config.id,kind:kind.value,prompt:prompt.value,parameters:{...parameters.value},reference_images:references.value.filter(item=>item.kind==='image').map(item=>item.path),reference_videos:references.value.filter(item=>item.kind==='video').map(item=>item.path),reference_audios:references.value.filter(item=>item.kind==='audio').map(item=>item.path)};const result=await modelTestAPI.create(body);if(!alive)return;const record={...result,kind:body.kind,modelLabel:config.display_name||modelsOf(config)[0],status:result.status||'running'};records.value.unshift(record);selectedRecordId.value=record.id;await refreshRecord(record)}catch(failure){error.value=failure.message}finally{sending.value=false}}
async function refreshRecord(record){try{const result=await modelTestAPI.get(record.id);if(alive){Object.assign(record,result);records.value=[...records.value]}}catch(failure){if(alive)error.value=failure.message}}
onMounted(()=>{loadModels();pollTimer=setInterval(()=>{if(document.visibilityState==='hidden')return;for(const record of records.value.filter(active))refreshRecord(record)},2000)})
onBeforeUnmount(()=>{alive=false;clearInterval(pollTimer)})
</script>
<style scoped>.playground-grid{display:grid;grid-template-columns:minmax(300px,410px) minmax(0,1fr);gap:19px}.test-compose,.test-results{overflow:hidden;min-width:0}.test-type-tabs{display:flex;padding:13px;border-bottom:1px solid var(--border);gap:7px}.test-type-tabs button{flex:1;border:0;border-radius:8px;display:flex;justify-content:center;align-items:center;gap:7px;padding:10px;background:transparent;color:var(--text-3);font-size:12px;cursor:pointer}.test-type-tabs button.on{background:var(--accent-bg);color:var(--accent-text);font-weight:600}.test-compose-body{padding:22px;display:grid;gap:20px}.test-field{display:grid;gap:9px;font-size:12px;font-weight:600}.test-field>.input{font-size:12px}.test-prompt{height:auto;resize:vertical;line-height:1.8}.test-note{font-size:10px;line-height:1.8;color:var(--text-3)}.test-reference-heading{display:flex;align-items:center;justify-content:space-between;gap:8px;font-size:11px;margin-bottom:12px}.test-reference-heading span{display:grid;gap:5px}.test-reference-heading small{font-size:9px;color:var(--text-3)}.test-reference-row{display:flex;align-items:center;gap:9px;padding:9px 0;border-bottom:1px solid var(--border)}.test-reference-row img,.test-reference-icon{height:35px;width:43px;object-fit:cover;border-radius:6px;background:var(--bg-2);display:grid;place-items:center}.test-reference-row>span:nth-child(2){flex:1;min-width:0}.test-reference-row strong{font-size:10px;display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.test-reference-row small{display:block;margin-top:4px;font-size:9px;color:var(--text-3)}.test-warning{font-size:10px;line-height:1.8;color:var(--warning);display:flex;gap:7px}.test-warning svg{flex-shrink:0;margin-top:2px}.test-error{color:var(--error);background:var(--error-bg);padding:12px;border-radius:8px;font-size:11px;line-height:1.8;overflow-wrap:anywhere}.test-send{width:100%}.test-results>header{padding:22px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--border);gap:10px}.test-results header span{font-size:8px;letter-spacing:.13em;color:var(--accent-text)}.test-results h2{font-size:17px;margin-top:7px}.test-history{display:flex;overflow:auto;gap:7px;padding:12px;border-bottom:1px solid var(--border)}.test-history button{border:1px solid var(--border);border-radius:7px;background:var(--bg-0);padding:7px 9px;font-size:9px;white-space:nowrap;color:var(--text-3);display:flex;align-items:center;gap:7px;cursor:pointer}.test-history button.on{color:var(--accent-text);background:var(--accent-bg)}.test-history i{width:5px;height:5px;border-radius:50%;background:var(--accent)}.test-history i.completed{background:var(--success)}.test-history i.failed{background:var(--error)}.test-result-body{display:grid;gap:20px;padding:23px}.test-result-meta{display:flex;gap:12px;align-items:center;font-size:10px;color:var(--text-3);flex-wrap:wrap}.test-state{background:var(--accent-bg);color:var(--accent-text);padding:4px 7px;border-radius:5px}.test-state.completed{color:var(--success);background:var(--success-bg)}.test-state.failed,.test-state.interrupted{color:var(--error);background:var(--error-bg)}.test-output{white-space:pre-wrap;overflow-wrap:anywhere;min-height:300px;border:1px solid var(--border);padding:18px;border-radius:10px;font:12px/1.9 var(--font-body);max-height:650px;overflow:auto}.test-result-image,.test-result-video{width:100%;max-height:620px;object-fit:contain;background:var(--bg-0);border-radius:10px}.test-idle{display:flex;align-items:center;justify-content:center;flex-direction:column;gap:18px;padding:75px 25px;min-height:400px;text-align:center;color:var(--text-3)}.test-idle h3{font-size:17px;color:var(--text-2)}.test-idle p{font-size:11px;line-height:1.8;max-width:320px}.test-progress span{font-size:11px;color:var(--accent-text)}.test-progress>div{height:5px;background:var(--bg-2);border-radius:99px;margin-top:9px;overflow:hidden}.test-progress i{display:block;height:100%;background:var(--accent);border-radius:99px}.test-gallery{display:flex;gap:9px;flex-wrap:wrap}.test-gallery button{border:1px solid var(--border);border-radius:8px;padding:6px;display:grid;gap:6px;background:var(--bg-0);font-size:9px;color:var(--text-3);cursor:pointer;min-width:78px;place-items:center}.test-gallery button.on{border-color:var(--accent);background:var(--accent-bg);color:var(--accent-text)}.test-gallery img{width:80px;height:58px;object-fit:cover;border-radius:5px}.test-download-list{display:flex;gap:10px;flex-wrap:wrap}.test-download-list a{font-size:10px;color:var(--accent-text);display:flex;align-items:center;gap:4px}.test-usage{border-top:1px solid var(--border);padding-top:14px;font-size:10px;color:var(--text-3)}.test-usage pre{font:10px/1.8 var(--font-mono);margin-top:8px}.test-log-overlay{position:fixed;inset:0;z-index:1400;padding:25px;background:var(--scrim);backdrop-filter:blur(5px);display:grid;place-items:center}.test-log-dialog{width:min(1380px,100%);height:min(880px,100%);border-radius:17px;overflow:hidden;background:var(--bg-1)}@media(max-width:1100px){.playground-grid{grid-template-columns:minmax(270px,340px) minmax(0,1fr)}}@media(max-width:850px){.playground-grid{grid-template-columns:1fr}.test-idle{min-height:250px}.test-log-overlay{padding:7px}}</style>
